/** The symbol as an SVG string, sized in em like a glyph of the surrounding text. */
export function sfSvg(name: string): string {
  const s = SF[name];
  if (!s) return "";
  const [w, h, t, d] = s;
  return `<svg class="sf" viewBox="0 0 ${w} ${h}" style="width:${w / 800}em;height:${h / 800}em" aria-hidden="true"><path transform="${t}" d="${d}"/></svg>`;
}
